// Adds ▶ Textbook / Natural / Slow buttons after each IPA whose Portuguese text has audio in manifest.json
// (generated by tools/tts.py; the text-finding rules here must match that script).
(function () {
  var base = document.currentScript.src.replace(/audio\.js.*$/, 'audio/');
  var norm = function (s) { return s.normalize('NFC').replace(/’/g, "'").replace(/\s+/g, ' ').trim(); };
  var player = new Audio();

  function prevElement(node) {
    for (var n = node.previousSibling; n; n = n.previousSibling) {
      if (n.nodeType === 3 && !n.textContent.trim()) continue;
      if (n.nodeName === 'BR') continue;
      return n.nodeType === 1 ? n : null;
    }
    return null;
  }

  function play(file, rate, version) {
    player.pause();
    player.src = base + file + '?' + version;
    player.playbackRate = rate;
    player.defaultPlaybackRate = rate;
    player.preservesPitch = true;
    player.currentTime = 0;
    player.play();
  }

  // ① Textbook (careful recording) · ② Natural · ③ Slow (the natural recording at 0.7x)
  function addButton(target, text, manifest) {
    var entry = manifest[norm(text)];
    if (!entry) return;
    var version = entry.voices.join('-') + '-' + (entry.model || '');
    var group = document.createElement('span');
    group.className = 'play-group';
    [['📖', 'Textbook', entry.textbook, 1], ['▶', 'Natural', entry.file, 1], ['🐢', 'Slow', entry.file, 0.7]].forEach(function (b) {
      if (!b[2]) return;
      var btn = document.createElement('button');
      btn.className = 'play';
      btn.type = 'button';
      btn.innerHTML = '<span class="play-icon">' + b[0] + '</span><span class="play-label"> ' + b[1] + '</span>';
      btn.title = b[1];
      btn.setAttribute('aria-label', 'Play ' + b[1].toLowerCase() + ' audio');
      btn.addEventListener('click', function () { play(b[2], b[3], version); });
      group.appendChild(btn);
    });
    target.appendChild(group);
  }

  fetch(base + 'manifest.json').then(function (r) { return r.ok ? r.json() : {}; }).then(function (manifest) {
    document.querySelectorAll('.content .ipa').forEach(function (ipa) {
      var p = prevElement(ipa);
      if (p && (p.nodeName === 'EM' || p.classList.contains('pt'))) addButton(ipa, p.textContent, manifest);
    });
    document.querySelectorAll('.content td').forEach(function (td) {
      if (!/^\/.*\/$/.test(td.textContent.trim())) return;
      var cells = Array.prototype.filter.call(td.parentNode.children, function (c) { return c !== td && c.querySelector('strong'); });
      if (cells.length) addButton(td, cells[cells.length - 1].textContent, manifest);
    });
  });
})();
